CREATE TABLE training_tasks(id TEXT PRIMARY KEY, family TEXT NOT NULL, form_id TEXT NOT NULL REFERENCES form_definitions(id), definition JSONB NOT NULL);
CREATE TABLE training_snapshots(id UUID PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), task_id TEXT NOT NULL REFERENCES training_tasks(id), sha256 TEXT NOT NULL, seed INTEGER NOT NULL, protocol JSONB NOT NULL, manifest JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE snapshot_invalidations(id UUID PRIMARY KEY, snapshot_id UUID NOT NULL REFERENCES training_snapshots(id) ON DELETE CASCADE, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE training_examples(id UUID PRIMARY KEY, snapshot_id UUID NOT NULL REFERENCES training_snapshots(id) ON DELETE CASCADE, participant_id UUID REFERENCES session_participants(id) ON DELETE CASCADE, session_id TEXT REFERENCES sessions(id) ON DELETE CASCADE, speaker_id TEXT REFERENCES speakers(id) ON DELETE CASCADE, mapping_id UUID REFERENCES speaker_mappings(id) ON DELETE CASCADE, submission_id UUID REFERENCES annotation_submissions(id) ON DELETE CASCADE, source_hash TEXT NOT NULL, role TEXT NOT NULL, feature_version TEXT NOT NULL, metadata JSONB NOT NULL, UNIQUE(snapshot_id,participant_id));
CREATE TABLE training_example_features(example_id UUID REFERENCES training_examples(id) ON DELETE CASCADE, name TEXT NOT NULL, value DOUBLE PRECISION, unit TEXT NOT NULL, status TEXT NOT NULL, denominator DOUBLE PRECISION, PRIMARY KEY(example_id,name));
CREATE TABLE training_example_labels(example_id UUID REFERENCES training_examples(id) ON DELETE CASCADE, answer_id UUID REFERENCES annotation_answers(id) ON DELETE CASCADE, target TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 4), adjudication_id UUID REFERENCES annotation_adjudications(id) ON DELETE CASCADE, PRIMARY KEY(example_id,target));
CREATE TABLE split_assignments(example_id UUID PRIMARY KEY REFERENCES training_examples(id) ON DELETE CASCADE, component TEXT NOT NULL, split TEXT NOT NULL CHECK(split IN ('train','validation','test')));
CREATE TABLE training_runs(id UUID PRIMARY KEY, snapshot_id UUID NOT NULL REFERENCES training_snapshots(id), owner_id TEXT NOT NULL REFERENCES users(id), job_id UUID REFERENCES jobs(id), status TEXT NOT NULL, configuration JSONB NOT NULL, versions JSONB NOT NULL, error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE training_run_events(id UUID PRIMARY KEY, run_id UUID REFERENCES training_runs(id) ON DELETE CASCADE, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE model_versions(id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES training_runs(id), family TEXT NOT NULL, target TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('candidate','active','retired','needs_retraining')), evaluation_status TEXT NOT NULL CHECK(evaluation_status IN ('exploratory','evaluated')), feature_schema JSONB NOT NULL, manifest JSONB NOT NULL, limitations JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE model_artifacts(id UUID PRIMARY KEY, model_id UUID NOT NULL REFERENCES model_versions(id), asset_id UUID NOT NULL REFERENCES assets(id), format TEXT NOT NULL);
CREATE TABLE model_evaluations(id UUID PRIMARY KEY, model_id UUID NOT NULL REFERENCES model_versions(id), split TEXT NOT NULL, n INTEGER NOT NULL, metrics JSONB NOT NULL, baseline JSONB NOT NULL, uncertainty JSONB NOT NULL);
CREATE TABLE model_deployments(id UUID PRIMARY KEY, model_id UUID NOT NULL REFERENCES model_versions(id), previous_model_id UUID REFERENCES model_versions(id), action TEXT NOT NULL CHECK(action IN ('activate','rollback','retire')), operator_id TEXT NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_target ON model_versions(family,target) WHERE status='active';
CREATE TABLE model_predictions(id UUID PRIMARY KEY, model_id UUID NOT NULL REFERENCES model_versions(id), session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, speaker_id TEXT NOT NULL REFERENCES speakers(id) ON DELETE CASCADE, input_revision INTEGER NOT NULL, score DOUBLE PRECISION, distribution JSONB, uncertainty JSONB NOT NULL, abstention TEXT, inputs JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE prediction_evidence(prediction_id UUID REFERENCES model_predictions(id) ON DELETE CASCADE, evidence_id TEXT REFERENCES evidence(id) ON DELETE CASCADE, PRIMARY KEY(prediction_id,evidence_id));
CREATE TRIGGER immutable_snapshots BEFORE UPDATE ON training_snapshots FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
CREATE TRIGGER immutable_examples BEFORE UPDATE ON training_examples FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
CREATE TRIGGER immutable_example_features BEFORE UPDATE ON training_example_features FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
CREATE TRIGGER immutable_example_labels BEFORE UPDATE ON training_example_labels FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
CREATE TRIGGER immutable_split_assignments BEFORE UPDATE ON split_assignments FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
